from sklearn.metrics import mean_absolute_error, mean_squared_error

def pred_seasonal_naive(train, target_date):
    # same month previous year if exists, else month avg
    prev=target_date-pd.DateOffset(years=1)
    if prev in train.index:
        return train.loc[prev]
    return train[train.index.month==target_date.month].mean()

def pred_month_avg(train, target_date):
    vals=train[train.index.month==target_date.month]
    if len(vals): return vals.mean()
    return train.mean()

def pred_month_avg_growth(train, target_date):
    vals=train[train.index.month==target_date.month]
    base=vals.mean() if len(vals) else train.mean()
    # estimate annual growth from yoy in train
    yoy=train/train.shift(12)-1
    g=np.nanmedian(yoy.dropna())
    if np.isnan(g): g=0
    # adjust base from mean vintage to future? for t target beyond average period of that month
    # maybe just last same month * median yoy
    prev=target_date-pd.DateOffset(years=1)
    if prev in train.index:
        return train.loc[prev]*(1+g)
    return base

def pred_ols(train, target_date, log=True):
    d=train.reset_index()
    d.columns=['date','sales_units']
    d['period_month']=d['date'].dt.month
    d['t']=np.arange(len(d))
    d['log_sales']=np.log(d['sales_units'])
    fut=pd.DataFrame({'period_month':[target_date.month], 't':[len(d)]})
    formula=('log_sales' if log else 'sales_units') + ' ~ C(period_month) + t'
    try:
        fit=sm.OLS.from_formula(formula, data=d).fit()
        p=fit.predict(fut).iloc[0]
        return np.exp(p) if log else p
    except Exception as e:
        return pred_month_avg(train,target_date)

def pred_ets(train, target_date, seasonal='add', trend=None):
    try:
        fit=ExponentialSmoothing(train.asfreq('MS'), trend=trend, seasonal=seasonal, seasonal_periods=12, initialization_method='estimated').fit(optimized=True)
        return fit.forecast(1).iloc[0]
    except Exception:
        return pred_seasonal_naive(train,target_date)

def pred_sarima(train, target_date, order=(1,0,1), seas=(0,1,1,12)):
    try:
        fit=SARIMAX(train.asfreq('MS'), order=order, seasonal_order=seas, trend='c', enforce_stationarity=False, enforce_invertibility=False).fit(disp=False, maxiter=100)
        return fit.forecast(1).iloc[0]
    except Exception:
        return pred_seasonal_naive(train,target_date)

methods = {
    'seasonal_naive': lambda tr,td: pred_seasonal_naive(tr,td),
    'month_avg': lambda tr,td: pred_month_avg(tr,td),
    'month_avg_growth': lambda tr,td: pred_month_avg_growth(tr,td),
    'ols_log': lambda tr,td: pred_ols(tr,td,log=True),
    'ols_linear': lambda tr,td: pred_ols(tr,td,log=False),
    'ets_add': lambda tr,td: pred_ets(tr,td,'add',None),
    'ets_mul': lambda tr,td: pred_ets(tr,td,'mul',None),
